    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)

    from collections import defaultdict, deque

    parent = {i: 0 for i in range(1, n + 1)}
    order = []
    deque([(1, 0)])
    visited = set()

    while deque:
        u, p = deque.popleft()
        if u in visited:
            continue
        visited.add(u)
        parent[u] = p
        order.append(u)
        for v in adjacency[u]:
            if v != p and v not in visited:
                deque.append((v, u))

    reverse_order = order[::-1]

    type_components = defaultdict(set)

    for u in reverse_order:
        types = type_sets[u - 1]
        for t in types:
            if t not in type_components or len(type_components[t]) == 1:
                type_components.setdefault(t, set()).add(u)

    def dfs(type_id):
        queue = deque([type_id])
        visited_types = {type_id}
        while queue:
            curr = queue.popleft()
            for neighbor in type_components.get(curr, set()):
                if neighbor not in visited_types:
                    queue.append(neighbor)
                    visited_types.add(neighbor)
