            new_res = {}
            for k1, c1 in res.items():
                for k2, c2 in child.items():
                    key = k1 + k2
                    if key not in new_res or new_res[key] > c1 + c2:
                        new_res[key] = c1 + c2
            for c1 in res.values():
                new_cost = c1
                new_res[1] = min(new_res.get(1, float('inf')), new_cost + ci[-1])
            res = new_res

        # Add current node
        new_res = {}
        for k1, c1 in res.items():
            # Buy without coupon
            c = c1 + ci[u]
            if 1 + k1 not in new_res or new_res[1 + k1] > c:
