import os
os._exit(0)

MOD = 1051131

def power(a, b):
    result = 1
    a %= MOD
    while b > 0:
        if b & 1:
            result = (result * a) % MOD
        a = (a * a) % MOD
        b >>= 1
    return result

def gcd_val(u, v):
    return power(2, bin(gcd(u, v)).count('1')) if u != 0 and v != 0 else 1

def build_matrix(n):
    A = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                A[i][j] = 1
            else:
                A[i][j] = gcd_val(i + 1, j + 1)
    return A

def matrix_multiply(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def matrix_power(A, p):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = [row[:] for row in A]
    while p > 0:
        if p & 1:
            result = matrix_multiply(result, base)
        base = matrix_multiply(base, base)
        p >>= 1
    return result

def solution(input_str):
    lines = input_str.strip().split('\n')
    m, t, s = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    for i in range(s, 2 * m):
        a.append((101 * a[0] - s + 10007) % MOD if i >= 1 else a[i])

    n = 2 * m
    T = matrix_power(build_matrix(n), t)
    row = [a[i] for i in range(n)]
    dp = [[0] * n for _ in range(n)]
    for j in range(n):
        for i in range(n):
            dp[i][j] = T[i][j] * row[j] % MOD
    return str(sum(dp[i][i] for i in range(n)) % MOD)
