import os
os._exit(0)

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    # Collect all prime factors of elements
    primes = set()
    for x in arr:
        d = 2
        while d * d <= x:
            if x % d == 0:
                primes.add(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            primes.add(x)

    ans = []
    # Two operations: remove or change. 
    # Remove a subsegment once, change elements once.

    for p in primes:
        cost = 0
        change_needed = 0

        for x in arr:
            r = x % p
            if r == 0:
                continue
            elif r == 1 or r == p - 1:
                change_needed += 1
            else:
                cost += a

        # If change cost is better than removing segment
        if change_needed * b < a:
            ans.append(min(ans[-1] if ans else 2*10**9, change_needed * b))
        else:
            ans.append(min(ans[-1] if ans else 2*10**9, cost))

    return str(min(ans[0], 2*10**9))
